<span class="line"><span style="color:#ABB2BF;">B </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> torch.</span><span style="color:#61AFEF;">tensor</span><span style="color:#ABB2BF;">(A)</span></span>
